1094|json_t *do_deep_copy(const json_t *json, hashtable_t *parents, int depth) {
1095|    if (!json)
1096|        return NULL;
1097|
1098|    if (depth >= JSON_PARSER_MAX_DEPTH)
1099|        return NULL;
1100|
1101|    switch (json_typeof(json)) {
1102|        case JSON_OBJECT:
1103|            return json_object_deep_copy(json, parents, depth);
1104|        case JSON_ARRAY:
1105|            return json_array_deep_copy(json, parents, depth);
1106|            /* for the rest of the types, deep copying doesn't differ from
1107|               shallow copying */
1108|        case JSON_STRING:
1109|            return json_string_copy(json);
1110|        case JSON_INTEGER:
1111|            return json_integer_copy(json);
1112|        case JSON_REAL:
1113|            return json_real_copy(json);
1114|        case JSON_TRUE:
1115|        case JSON_FALSE:
1116|        case JSON_NULL:
1117|            return (json_t *)json;
1118|        default:
1119|            return NULL;
1120|    }
1121|}

