313|static void max_depth() {
314|    json_t *json;
315|    char *result;
316|
317|    /* A structure nested exactly to the limit must still serialize. */
318|    json = build_nested_array(JSON_PARSER_MAX_DEPTH);
319|    result = json_dumps(json, 0);
320|    if (!result)
321|        fail("json_dumps failed for a structure within the depth limit");
322|    free(result);
323|    json_decref(json);
324|
325|    /* A structure nested deeper than the limit must fail cleanly rather
326|       than overflow the stack. */
327|    json = build_nested_array(JSON_PARSER_MAX_DEPTH + 100);
328|    if (json_dumps(json, 0) != NULL)
329|        fail("json_dumps didn't fail for a too deeply nested structure");
330|    json_decref(json);
