480|int json_dump_callback(const json_t *json, json_dump_callback_t callback, void *data,
481|                       size_t flags) {
482|    int res;
483|    hashtable_t parents_set;
484|
485|    if (!(flags & JSON_ENCODE_ANY)) {
486|        if (!json_is_array(json) && !json_is_object(json))
487|            return -1;
488|    }
489|
490|    if (hashtable_init(&parents_set))
491|        return -1;
492|    res = do_dump(json, flags, 0, &parents_set, callback, data);
493|    hashtable_close(&parents_set);
494|
495|    return res;
