215|static int do_dump(const json_t *json, size_t flags, int depth, hashtable_t *parents,
216|                   json_dump_callback_t dump, void *data) {
217|    int embed = flags & JSON_EMBED;
218|
219|    flags &= ~JSON_EMBED;
220|
221|    if (!json)
222|        return -1;
223|
224|    if (depth >= JSON_PARSER_MAX_DEPTH)
225|        return -1;
226|
227|    switch (json_typeof(json)) {
228|        case JSON_NULL:
229|            return dump("null", 4, data);
230|
231|        case JSON_TRUE:
232|            return dump("true", 4, data);
233|
234|        case JSON_FALSE:
235|            return dump("false", 5, data);
236|
237|        case JSON_INTEGER: {
238|            char buffer[MAX_INTEGER_STR_LENGTH];
239|            int size;
240|
241|            size = snprintf(buffer, MAX_INTEGER_STR_LENGTH, "%" JSON_INTEGER_FORMAT,
242|                            json_integer_value(json));
243|            if (size < 0 || size >= MAX_INTEGER_STR_LENGTH)
244|                return -1;
245|
246|            return dump(buffer, size, data);
247|        }
248|
249|        case JSON_REAL: {
250|            char buffer[MAX_REAL_STR_LENGTH];
251|            int size;
252|            double value = json_real_value(json);
253|
254|            size = jsonp_dtostr(buffer, MAX_REAL_STR_LENGTH, value,
255|                                FLAGS_TO_PRECISION(flags));
256|            if (size < 0)
257|                return -1;
258|
259|            return dump(buffer, size, data);
260|        }
261|
262|        case JSON_STRING:
263|            return dump_string(json_string_value(json), json_string_length(json), dump,
264|                               data, flags);
265|
266|        case JSON_ARRAY: {
267|            size_t n;
268|            size_t i;
269|            /* Space for "0x", double the sizeof a pointer for the hex and a
270|             * terminator. */
271|            char key[2 + (sizeof(json) * 2) + 1];
272|            size_t key_len;
273|
274|            /* detect circular references */
275|            if (jsonp_loop_check(parents, json, key, sizeof(key), &key_len))
276|                return -1;
277|
278|            n = json_array_size(json);
279|
280|            if (!embed && dump("[", 1, data))
281|                return -1;
282|            if (n == 0) {
283|                hashtable_del(parents, key, key_len);
284|                return embed ? 0 : dump("]", 1, data);
285|            }
286|            if (dump_indent(flags, depth + 1, 0, dump, data))
287|                return -1;
288|
289|            for (i = 0; i < n - 1; ++i) {
290|                if (do_dump(json_array_get(json, i), flags, depth + 1, parents, dump,
291|                            data))
292|                    return -1;
293|
294|                if (dump(",", 1, data) || dump_indent(flags, depth + 1, 1, dump, data))
295|                    return -1;
296|            }
297|
298|            if (do_dump(json_array_get(json, i), flags, depth + 1, parents, dump, data))
299|                return -1;
300|            if (dump_indent(flags, depth, 0, dump, data))
301|                return -1;
302|
303|            hashtable_del(parents, key, key_len);
304|            return embed ? 0 : dump("]", 1, data);
305|        }
306|
307|        case JSON_OBJECT: {
308|            void *iter;
309|            const char *separator;
310|            int separator_length;
311|            char loop_key[LOOP_KEY_LEN];
312|            size_t loop_key_len;
313|
314|            if (flags & JSON_COMPACT) {
315|                separator = ":";
316|                separator_length = 1;
317|            } else {
318|                separator = ": ";
319|                separator_length = 2;
320|            }
321|
322|            /* detect circular references */
323|            if (jsonp_loop_check(parents, json, loop_key, sizeof(loop_key),
324|                                 &loop_key_len))
325|                return -1;
326|
327|            if (!embed && dump("{", 1, data))
328|                return -1;
329|
330|            iter = json_object_iter((json_t *)json);
331|            if (!iter) {
332|                hashtable_del(parents, loop_key, loop_key_len);
333|                return embed ? 0 : dump("}", 1, data);
334|            }
335|            if (dump_indent(flags, depth + 1, 0, dump, data))
336|                return -1;
337|
338|            if (flags & JSON_SORT_KEYS) {
339|                struct key_len *keys;
340|                size_t size, i;
341|
342|                size = json_object_size(json);
343|                keys = jsonp_malloc(size * sizeof(struct key_len));
344|                if (!keys)
345|                    return -1;
346|
347|                i = 0;
348|                while (iter) {
349|                    struct key_len *keylen = &keys[i];
350|
351|                    keylen->key = json_object_iter_key(iter);
352|                    keylen->len = json_object_iter_key_len(iter);
353|
354|                    iter = json_object_iter_next((json_t *)json, iter);
355|                    i++;
356|                }
357|                assert(i == size);
358|
359|                qsort(keys, size, sizeof(struct key_len), compare_keys);
360|
361|                for (i = 0; i < size; i++) {
362|                    const struct key_len *key;
363|                    json_t *value;
364|
365|                    key = &keys[i];
366|                    value = json_object_getn(json, key->key, key->len);
367|                    assert(value);
368|
369|                    dump_string(key->key, key->len, dump, data, flags);
370|                    if (dump(separator, separator_length, data) ||
371|                        do_dump(value, flags, depth + 1, parents, dump, data)) {
372|                        jsonp_free(keys);
373|                        return -1;
374|                    }
375|
376|                    if (i < size - 1) {
377|                        if (dump(",", 1, data) ||
378|                            dump_indent(flags, depth + 1, 1, dump, data)) {
379|                            jsonp_free(keys);
380|                            return -1;
381|                        }
382|                    } else {
383|                        if (dump_indent(flags, depth, 0, dump, data)) {
384|                            jsonp_free(keys);
385|                            return -1;
386|                        }
387|                    }
388|                }
389|
390|                jsonp_free(keys);
391|            } else {
392|                /* Don't sort keys */
393|
394|                while (iter) {
395|                    void *next = json_object_iter_next((json_t *)json, iter);
396|                    const char *key = json_object_iter_key(iter);
397|                    const size_t key_len = json_object_iter_key_len(iter);
398|
399|                    dump_string(key, key_len, dump, data, flags);
400|                    if (dump(separator, separator_length, data) ||
401|                        do_dump(json_object_iter_value(iter), flags, depth + 1, parents,
402|                                dump, data))
403|                        return -1;
404|
405|                    if (next) {
406|                        if (dump(",", 1, data) ||
407|                            dump_indent(flags, depth + 1, 1, dump, data))
408|                            return -1;
409|                    } else {
410|                        if (dump_indent(flags, depth, 0, dump, data))
411|                            return -1;
412|                    }
413|
414|                    iter = next;
415|                }
416|            }
417|
418|            hashtable_del(parents, loop_key, loop_key_len);
419|            return embed ? 0 : dump("}", 1, data);
420|        }
421|
422|        default:
423|            /* not reached */
424|            return -1;
425|    }
426|}
