215|static int do_dump(const json_t *json, size_t flags, int depth, hashtable_t *parents,
216|                   json_dump_callback_t dump, void *data) {
217|    int embed = flags & JSON_EMBED;
218|
219|    flags &= ~JSON_EMBED;
220|
221|    if (!json)
222|        return -1;
223|
224|    switch (json_typeof(json)) {
225|        case JSON_NULL:
226|            return dump("null", 4, data);
227|
228|        case JSON_TRUE:
229|            return dump("true", 4, data);
230|
231|        case JSON_FALSE:
232|            return dump("false", 5, data);
233|
234|        case JSON_INTEGER: {
235|            char buffer[MAX_INTEGER_STR_LENGTH];
236|            int size;
237|
238|            size = snprintf(buffer, MAX_INTEGER_STR_LENGTH, "%" JSON_INTEGER_FORMAT,
239|                            json_integer_value(json));
240|            if (size < 0 || size >= MAX_INTEGER_STR_LENGTH)
241|                return -1;
242|
243|            return dump(buffer, size, data);
244|        }
245|
246|        case JSON_REAL: {
247|            char buffer[MAX_REAL_STR_LENGTH];
248|            int size;
249|            double value = json_real_value(json);
250|
251|            size = jsonp_dtostr(buffer, MAX_REAL_STR_LENGTH, value,
252|                                FLAGS_TO_PRECISION(flags));
253|            if (size < 0)
254|                return -1;
255|
256|            return dump(buffer, size, data);
257|        }
258|
259|        case JSON_STRING:
260|            return dump_string(json_string_value(json), json_string_length(json), dump,
261|                               data, flags);
262|
263|        case JSON_ARRAY: {
264|            size_t n;
265|            size_t i;
266|            /* Space for "0x", double the sizeof a pointer for the hex and a
267|             * terminator. */
268|            char key[2 + (sizeof(json) * 2) + 1];
269|            size_t key_len;
270|
271|            /* detect circular references */
272|            if (jsonp_loop_check(parents, json, key, sizeof(key), &key_len))
273|                return -1;
274|
275|            n = json_array_size(json);
276|
277|            if (!embed && dump("[", 1, data))
278|                return -1;
279|            if (n == 0) {
280|                hashtable_del(parents, key, key_len);
281|                return embed ? 0 : dump("]", 1, data);
282|            }
283|            if (dump_indent(flags, depth + 1, 0, dump, data))
284|                return -1;
285|
286|            for (i = 0; i < n - 1; ++i) {
287|                if (do_dump(json_array_get(json, i), flags, depth + 1, parents, dump,
288|                            data))
289|                    return -1;
290|
291|                if (dump(",", 1, data) || dump_indent(flags, depth + 1, 1, dump, data))
292|                    return -1;
293|            }
294|
295|            if (do_dump(json_array_get(json, i), flags, depth + 1, parents, dump, data))
296|                return -1;
297|            if (dump_indent(flags, depth, 0, dump, data))
298|                return -1;
299|
300|            hashtable_del(parents, key, key_len);
301|            return embed ? 0 : dump("]", 1, data);
302|        }
303|
304|        case JSON_OBJECT: {
305|            void *iter;
306|            const char *separator;
307|            int separator_length;
308|            char loop_key[LOOP_KEY_LEN];
309|            size_t loop_key_len;
310|
311|            if (flags & JSON_COMPACT) {
312|                separator = ":";
313|                separator_length = 1;
314|            } else {
315|                separator = ": ";
316|                separator_length = 2;
317|            }
318|
319|            /* detect circular references */
320|            if (jsonp_loop_check(parents, json, loop_key, sizeof(loop_key),
321|                                 &loop_key_len))
322|                return -1;
323|
324|            if (!embed && dump("{", 1, data))
325|                return -1;
326|
327|            iter = json_object_iter((json_t *)json);
328|            if (!iter) {
329|                hashtable_del(parents, loop_key, loop_key_len);
330|                return embed ? 0 : dump("}", 1, data);
331|            }
332|            if (dump_indent(flags, depth + 1, 0, dump, data))
333|                return -1;
334|
335|            if (flags & JSON_SORT_KEYS) {
336|                struct key_len *keys;
337|                size_t size, i;
338|
339|                size = json_object_size(json);
340|                keys = jsonp_malloc(size * sizeof(struct key_len));
341|                if (!keys)
342|                    return -1;
343|
344|                i = 0;
345|                while (iter) {
346|                    struct key_len *keylen = &keys[i];
347|
348|                    keylen->key = json_object_iter_key(iter);
349|                    keylen->len = json_object_iter_key_len(iter);
350|
351|                    iter = json_object_iter_next((json_t *)json, iter);
352|                    i++;
353|                }
354|                assert(i == size);
355|
356|                qsort(keys, size, sizeof(struct key_len), compare_keys);
357|
358|                for (i = 0; i < size; i++) {
359|                    const struct key_len *key;
360|                    json_t *value;
361|
362|                    key = &keys[i];
363|                    value = json_object_getn(json, key->key, key->len);
364|                    assert(value);
365|
366|                    dump_string(key->key, key->len, dump, data, flags);
367|                    if (dump(separator, separator_length, data) ||
368|                        do_dump(value, flags, depth + 1, parents, dump, data)) {
369|                        jsonp_free(keys);
370|                        return -1;
371|                    }
372|
373|                    if (i < size - 1) {
374|                        if (dump(",", 1, data) ||
375|                            dump_indent(flags, depth + 1, 1, dump, data)) {
376|                            jsonp_free(keys);
377|                            return -1;
378|                        }
379|                    } else {
380|                        if (dump_indent(flags, depth, 0, dump, data)) {
381|                            jsonp_free(keys);
382|                            return -1;
383|                        }
384|                    }
385|                }
386|
387|                jsonp_free(keys);
388|            } else {
389|                /* Don't sort keys */
390|
391|                while (iter) {
392|                    void *next = json_object_iter_next((json_t *)json, iter);
393|                    const char *key = json_object_iter_key(iter);
394|                    const size_t key_len = json_object_iter_key_len(iter);
395|
396|                    dump_string(key, key_len, dump, data, flags);
397|                    if (dump(separator, separator_length, data) ||
398|                        do_dump(json_object_iter_value(iter), flags, depth + 1, parents,
399|                                dump, data))
400|                        return -1;
401|
402|                    if (next) {
403|                        if (dump(",", 1, data) ||
404|                            dump_indent(flags, depth + 1, 1, dump, data))
405|                            return -1;
406|                    } else {
407|                        if (dump_indent(flags, depth, 0, dump, data))
408|                            return -1;
409|                    }
410|
411|                    iter = next;
412|                }
413|            }
414|
415|            hashtable_del(parents, loop_key, loop_key_len);
416|            return embed ? 0 : dump("}", 1, data);
417|        }
418|
419|        default:
420|            /* not reached */
421|            return -1;
422|    }
423|}

776|static json_t *parse_value(lex_t *lex, size_t flags, json_error_t *error) {
777|    json_t *json;
